import { Component, OnInit } from '@angular/core';
import { Router, ActivatedRoute, RouterModule } from '@angular/router';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { first } from 'rxjs/operators';
import { AccountService, AlertService } from '@app/_services';

@Component({
  selector: 'app-add-edit',
  templateUrl: './add-edit.component.html',
  styleUrls: ['./add-edit.component.less'],
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, RouterModule]
})
export class AddEditComponent implements OnInit {
  form!: FormGroup;
  loading = false;
  submitted = false;
  isAddMode?: boolean;
  id?: string;

  constructor(
    private formBuilder: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private accountService: AccountService,
    private alertService: AlertService
  ) { }

  ngOnInit() {
    this.id = this.route.snapshot.params['id'];
    this.isAddMode = !this.id;

    const passwordValidators = [Validators.minLength(6)];
    if (this.isAddMode) {
      passwordValidators.push(Validators.required);
    }

    this.form = this.formBuilder.group({
      title: ['', Validators.required],
      firstName: ['', Validators.required],
      lastName: ['', Validators.required],
      email: ['', [Validators.required, Validators.email]],
      password: ['', passwordValidators],
      role: ['', Validators.required]
    });

    if (!this.isAddMode) {
      this.accountService.getById(this.id || '')
        .pipe(first())
        .subscribe({
          next: (account: any) => {
            this.form.patchValue(account);
          },
          error: (error: any) => {
            this.alertService.error(error);
          }
        });
    }
  }

  get f() {
    return this.form.controls;
  }

  onSubmit() {
    this.submitted = true;

    if (this.form.invalid) {
      return;
    }

    this.loading = true;
    if (this.isAddMode) {
      this.accountService.create(this.form.value)
        .pipe(first())
        .subscribe({
          next: () => {
            this.alertService.success('Account added successfully', { keepAfterRouteChange: true });
            this.router.navigate(['/admin/accounts']);
          },
          error: (error: any) => {
            this.alertService.error(error);
            this.loading = false;
          }
        });
    } else {
      this.accountService.update(this.id || '', this.form.value)
        .pipe(first())
        .subscribe({
          next: () => {
            this.alertService.success('Account updated successfully', { keepAfterRouteChange: true });
            this.router.navigate(['/admin/accounts']);
          },
          error: (error: any) => {
            this.alertService.error(error);
            this.loading = false;
          }
        });
    }
  }
}
<div class="p-4">
  <h1>{{ isAddMode ? 'Add Account' : 'Edit Account' }}</h1>

  <form [formGroup]="form" (ngSubmit)="onSubmit()">
    <div class="mb-3">
      <label class="form-label">Title</label>
      <select formControlName="title" class="form-select">
        <option value=""></option>
        <option value="Mr">Mr</option>
        <option value="Mrs">Mrs</option>
        <option value="Miss">Miss</option>
        <option value="Ms">Ms</option>
      </select>
      <div *ngIf="submitted && f['title'].errors" class="text-danger">Title is required</div>
    </div>
    <div class="mb-3">
      <label class="form-label">First Name</label>
      <input type="text" formControlName="firstName" class="form-control" />
      <div *ngIf="submitted && f['firstName'].errors" class="text-danger">First Name is required</div>
    </div>
    <div class="mb-3">
      <label class="form-label">Last Name</label>
      <input type="text" formControlName="lastName" class="form-control" />
      <div *ngIf="submitted && f['lastName'].errors" class="text-danger">Last Name is required</div>
    </div>
    <div class="mb-3">
      <label class="form-label">Email</label>
      <input type="text" formControlName="email" class="form-control" />
      <div *ngIf="submitted && f['email'].errors" class="text-danger">
        <div *ngIf="f['email'].errors['required']">Email is required</div>
        <div *ngIf="f['email'].errors['email']">Email must be a valid email address</div>
      </div>
    </div>
    <div class="mb-3" *ngIf="isAddMode">
      <label class="form-label">Password</label>
      <input type="password" formControlName="password" class="form-control" />
      <div *ngIf="submitted && f['password'].errors" class="text-danger">
        <div *ngIf="f['password'].errors['required']">Password is required</div>
        <div *ngIf="f['password'].errors['minlength']">Password must be at least 6 characters</div>
      </div>
    </div>
    <div class="mb-3">
      <label class="form-label">Role</label>
      <select formControlName="role" class="form-select">
        <option value=""></option>
        <option value="User">User</option>
        <option value="Admin">Admin</option>
      </select>
      <div *ngIf="submitted && f['role'].errors" class="text-danger">Role is required</div>
    </div>
    <button [disabled]="form.invalid || loading" class="btn btn-primary">
      <span *ngIf="loading" class="spinner-border spinner-border-sm me-2"></span>
      {{ isAddMode ? 'Create' : 'Update' }}
    </button>
    <a routerLink="/admin/accounts" class="btn btn-secondary ms-2">Cancel</a>
  </form>
</div>
